#include <set>
#include <iostream>
#include <algorithm>

int main() {
    std::multiset<int> ms = {10, 20, 20, 30, 40};
    int key = 20;

    // Use equal_range to get the full range [first >= key, first > key)
    auto range = ms.equal_range(key);

    std::cout << "Elements equivalent to " << key << ": ";
    for (auto it = range.first; it != range.second; ++it) {
        std::cout << *it << " ";
    }
    std::cout << "\n";
}
